import{Z as t,e as r,f as o,a0 as s}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Scheduled Reports","description":"","frontmatter":{},"headers":[],"relativePath":"reports/scheduled-reports.md","filePath":"reports/scheduled-reports.md","lastUpdated":1782912477000}'),n={name:"reports/scheduled-reports.md"};function a(i,e,d,l,h,c){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="scheduled-reports" tabindex="-1">Scheduled Reports <a class="header-anchor" href="#scheduled-reports" aria-label="Permalink to &quot;Scheduled Reports&quot;">​</a></h1><p>Scheduled reports email a saved report on a daily or weekly cadence. Each delivery sends:</p><ul><li>a <strong>summary email</strong> with submission counts (and per-form breakdown when multiple forms match)</li><li>an <strong>export attachment</strong> in the file type you choose, using the report’s filters, columns, and export filename setting</li></ul><p>Configure schedules under <strong>Formie → Settings → Scheduled Reports</strong>, or from a report&#39;s <strong>Scheduled</strong> tab (<strong>Formie → Reports → {report} → Edit → Scheduled</strong>).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For a getting-started walkthrough, see <a href="/guides/submissions-workflows/saved-reports-and-scheduled-delivery">Saved reports and scheduled delivery</a>.</p></div><h2 id="before-you-start-cron" tabindex="-1">Before You Start: Cron <a class="header-anchor" href="#before-you-start-cron" aria-label="Permalink to &quot;Before You Start: Cron&quot;">​</a></h2><p>Deliveries do <strong>not</strong> send by themselves. They run when a console command executes on a server cron schedule — typically every hour:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> formie/cron/run</span></span></code></pre></div><p>You can also run only scheduled reports:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> formie/reports/run-scheduled</span></span></code></pre></div><p>Or run cleanup and reports on separate schedules with <code>--only=reports</code> or <code>--only=gc</code>. See <a href="/developers/console-commands#cron">Console commands — Cron</a>.</p><p>If no cron command is scheduled, enabled scheduled reports will never send. Use <strong>Send Test Email</strong> on an existing scheduled report to verify delivery without waiting for cron.</p><h2 id="creating-a-scheduled-report" tabindex="-1">Creating a Scheduled Report <a class="header-anchor" href="#creating-a-scheduled-report" aria-label="Permalink to &quot;Creating a Scheduled Report&quot;">​</a></h2><ol><li>Create and save a <a href="/reports/reports">report</a> with the filters and columns you want.</li><li>Open <strong>Settings → Scheduled Reports</strong> (or the report’s <strong>Scheduled</strong> tab) and choose <strong>New Scheduled Report</strong>.</li><li>Set <strong>Name</strong>, <strong>Report</strong>, and <strong>Enabled</strong>.</li><li>Under <strong>Schedule</strong>, choose <strong>Frequency</strong> (daily or weekly), <strong>Day of Week</strong> (weekly only), <strong>Hour</strong> (0–23, control panel timezone), and optional <strong>Start Date</strong> / <strong>End Date</strong>.</li><li>Under <strong>Delivery</strong>, set <strong>File Type</strong>, <strong>Recipients</strong> (comma- or line-separated addresses), optional <strong>Recipient User Group</strong>, <strong>Email Subject</strong>, <strong>Email Message</strong>, and optional <strong>Email Template</strong>.</li></ol><h3 id="file-type" tabindex="-1">File Type <a class="header-anchor" href="#file-type" aria-label="Permalink to &quot;File Type&quot;">​</a></h3><p><strong>File Type</strong> controls the attached export format:</p><table tabindex="0"><thead><tr><th>File type</th><th>Extension</th></tr></thead><tbody><tr><td><strong>Excel</strong></td><td><code>.xlsx</code></td></tr><tr><td><strong>CSV</strong></td><td><code>.csv</code></td></tr><tr><td><strong>JSON</strong></td><td><code>.json</code></td></tr><tr><td><strong>XML</strong></td><td><code>.xml</code></td></tr><tr><td><strong>Text</strong></td><td><code>.txt</code></td></tr></tbody></table><p>These match the formats available from the report run screen <strong>Export</strong> menu. The file extension is added automatically from <strong>File Type</strong>; the <strong>Export Filename</strong> on the linked report controls the basename only.</p><p>Leave <strong>Email Subject</strong> blank to use the report name. Leave <strong>Email Message</strong> blank to send only the summary table and attachment. Leave <strong>Email Template</strong> blank to use Formie’s default email wrapper — the same behaviour as notification emails.</p><h2 id="incremental-export-windows" tabindex="-1">Incremental Export Windows <a class="header-anchor" href="#incremental-export-windows" aria-label="Permalink to &quot;Incremental Export Windows&quot;">​</a></h2><p>After the first successful delivery, the attachment includes submissions created <strong>since the previous delivery</strong> (<code>lastSentAt</code>), while still respecting the report’s saved filters.</p><p>The email summary counts use the same incremental window. The first delivery includes all submissions matching the report filters.</p><p>Test sends use the full current report filters and do <strong>not</strong> update <code>lastSentAt</code>. They send to the signed-in user who runs the test, not to the configured recipient list. This checks rendering and delivery to your own mailbox; verify the intended recipients separately and inspect the first scheduled delivery.</p><h2 id="save-before-testing" tabindex="-1">Save Before Testing <a class="header-anchor" href="#save-before-testing" aria-label="Permalink to &quot;Save Before Testing&quot;">​</a></h2><p>Actions in the save menu (<strong>Send Test Email</strong>, <strong>Delete</strong>) use the scheduled report as stored in the database. Save your changes before sending a test email if you have edited recipients, schedule, file type, or message fields.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Users need <strong>Manage scheduled reports</strong> to create, edit, delete, or test scheduled delivery. Viewing the <strong>Scheduled</strong> tab on a report requires the same permission.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="nothing-sends-on-schedule" tabindex="-1">Nothing Sends on Schedule <a class="header-anchor" href="#nothing-sends-on-schedule" aria-label="Permalink to &quot;Nothing Sends on Schedule&quot;">​</a></h3><p>Confirm <code>./craft formie/cron/run</code> (or <code>./craft formie/reports/run-scheduled</code>) is on cron and that the scheduled report is <strong>Enabled</strong>, within any start/end dates, and due for the current hour/day.</p><p>Run the command manually and check the console output for errors.</p><h3 id="test-email-works-but-cron-does-not" tabindex="-1">Test Email Works but Cron Does Not <a class="header-anchor" href="#test-email-works-but-cron-does-not" aria-label="Permalink to &quot;Test Email Works but Cron Does Not&quot;">​</a></h3><p>Usually the cron job is missing, pointed at the wrong PHP binary, or not running frequently enough. Weekly schedules only send on the chosen weekday after the configured hour.</p><h3 id="attachment-is-empty" tabindex="-1">Attachment Is Empty <a class="header-anchor" href="#attachment-is-empty" aria-label="Permalink to &quot;Attachment Is Empty&quot;">​</a></h3><p>If the incremental window has no new submissions since the last delivery, the attachment may contain headers only (or an empty structure for JSON/XML). Run a test send or check <code>lastSentAt</code> on the scheduled report record.</p><p>Large attachments may be omitted when they exceed the plugin’s maximum email attachment size. Check Craft logs for a warning.</p>',36)])])}const g=t(n,[["render",a]]);export{u as __pageData,g as default};
